script:
set d to XMLOpen (POSIX file "$FILES/simple.xml")
set r to XMLRoot d
XMLSetContext d xpath variables {"v", "b1"}
XMLXPath r with "book[@id=$v]/title" xpath variables {"v", "b2"}
XMLClose d

set d to XMLOpen (POSIX file "$FILES/simple.xml")
XMLXPointer "#xpointer(//dc:creator)" from d namespace {nsprefix:"dc", nsurl:"http://purl.org/dc/elements/1.1/"}
XMLClose d
